#include <iostream>
#include <string>
#include <cctype>

using namespace std;

/**
 * Problem: 2008-06 - Parser and evaluator
 * 
 * 解題思路：
 * 1. 使用遞迴下降解析法 (Recursive Descent Parser)。
 * 2. 語法：
 *    E -> T { (+|-) T }
 *    T -> F { (*|/|%) F }
 *    F -> ( E ) | -F | +F | Number
 */

string expr;
int pos;

int parseE();
int parseT();
int parseF();

int parseE() {
    int res = parseT();
    while (pos < expr.length() && (expr[pos] == '+' || expr[pos] == '-')) {
        char op = expr[pos++];
        int right = parseT();
        if (op == '+') res += right;
        else res -= right;
    }
    return res;
}

int parseT() {
    int res = parseF();
    while (pos < expr.length() && (expr[pos] == '*' || expr[pos] == '/' || expr[pos] == '%')) {
        char op = expr[pos++];
        int right = parseF();
        if (op == '*') res *= right;
        else if (op == '/') res /= right;
        else res %= right;
    }
    return res;
}

int parseF() {
    if (expr[pos] == '(') {
        pos++;
        int res = parseE();
        pos++; // skip ')'
        return res;
    } else if (expr[pos] == '-') {
        pos++;
        return -parseF();
    } else if (expr[pos] == '+') {
        pos++;
        return parseF();
    } else {
        int res = 0;
        while (pos < expr.length() && isdigit(expr[pos])) {
            res = res * 10 + (expr[pos++] - '0');
        }
        return res;
    }
}

int main() {
    while (getline(cin, expr)) {
        if (expr.empty()) continue;
        // 移除空格
        string clean = "";
        for (char c : expr) if (!isspace(c)) clean += c;
        expr = clean;
        pos = 0;
        cout << parseE() << endl;
    }
    return 0;
}
